src/main/java/net/officefloor/hq/app/rollup/Rollup.java:208:    public void recordAll(String sheetId, String user) {
-- The sheet's pot: shared out among the members of each balanced pool by their shares. None means no pot.
-- Not dated.
ALTER TABLE sheet ADD COLUMN pot NUMERIC(15,2) CHECK (pot >= 0);

    /** Change the sheet's fiscal start month (1 to 12). Not dated. */
    @Transactional
    public Sheet setFiscalStartMonth(String id, String user, int month) {
        Sheet sheet = sheets.findForUpdateById(id).orElseThrow(SheetNotFoundException::new);
        sheet.setFiscalStartMonth(month);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=fiscal-start-month value=" + month);
        return sheet;
    }

    /** Change the sheet's pot (none: no pot). Not dated. */
    @Transactional
    public Sheet setPot(String id, String user, BigDecimal pot) {
        Sheet sheet = sheets.findForUpdateById(id).orElseThrow(SheetNotFoundException::new);
        BigDecimal p = pot == null ? null : pot.setScale(2);
        sheet.setPot(p);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=pot value="
                + (p == null ? "" : p.toPlainString()));
        return sheet;
    }

    /** Change the sheet's parent (none: no parent), recording the figures it moves. Not dated. The sheet
     *  cannot be its own parent, nor name a sheet that has it as an ancestor, and the parent must exist. */
    @Transactional
    public Sheet setParent(String id, String user, String parent) {
        Sheet sheet = sheets.findForUpdateById(id).orElseThrow(SheetNotFoundException::new);
        return sheet;
    }

    private void copySheet(Sheet sheet, String target, String user) {
        String id = sheet.getId();
        jdbc.update("INSERT INTO sheet (id, created_by, created_at, today, last_claim_number, last_settle_batch,"
                + " policy_date, period_numbering_from, grace_days, archived, entry_date, pot, parent)"
                + " SELECT ?, ?, ?, today, 0, last_settle_batch, policy_date, period_numbering_from, grace_days, FALSE,"
                + " entry_date, pot, parent FROM sheet WHERE id = ?", target, user, Timestamp.from(Instant.now()), id);
        jdbc.update("INSERT INTO sheet_setting (sheet_id, setting_key, from_date, setting_value)"
                + " SELECT ?, setting_key, from_date, setting_value FROM sheet_setting WHERE sheet_id = ?", target, id);
        jdbc.update("INSERT INTO sheet_permission (sheet_id, action, roles)"
                + " SELECT ?, action, roles FROM sheet_permission WHERE sheet_id = ?", target, id);
        jdbc.update("INSERT INTO sheet_role (sheet_id, user_name, role)"
                + " SELECT ?, user_name, role FROM sheet_role WHERE sheet_id = ? ORDER BY id", target, id);
        jdbc.update("INSERT INTO rate (sheet_id, grade, rate, from_date, to_date)"
                + " SELECT ?, grade, rate, from_date, to_date FROM rate WHERE sheet_id = ? ORDER BY id", target, id);
        jdbc.update("INSERT INTO holiday (sheet_id, holiday_date)"
                + " SELECT ?, holiday_date FROM holiday WHERE sheet_id = ? ORDER BY id", target, id);
        jdbc.update("INSERT INTO void_reason (sheet_id, reason)"
                + " SELECT ?, reason FROM void_reason WHERE sheet_id = ? ORDER BY id", target, id);
        jdbc.update("INSERT INTO claim_template (sheet_id, name, amount, note)"
                + " SELECT ?, name, amount, note FROM claim_template WHERE sheet_id = ? ORDER BY id", target, id);
        jdbc.update("INSERT INTO sheet_tag (sheet_id, tag)"
                + " SELECT ?, tag FROM sheet_tag WHERE sheet_id = ? ORDER BY id", target, id);
    }

