        this.limitTouched.set(false);
        this.floor.set('');
        this.floorTouched.set(false);
        this.cap.set('');
        this.capTouched.set(false);
        this.proofThreshold.set('');
        this.proofThresholdTouched.set(false);
        this.noteThreshold.set('');
        this.noteThresholdTouched.set(false);
